inline MutationValues Platform::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (auto relation = std::move(priority_list_).into_value()) {
        values.fields.emplace(String("priority_list", r), std::move(*relation));
    }
    if (auto relation = std::move(label_list_).into_value()) {
        values.fields.emplace(String("label_list", r), std::move(*relation));
    }
    inject_runtime(values);
    return values;
}

inline const Platform* Label::platform() const {
    if (platform_) {
        return platform_.get();
    }
    if (!is_loaded("platform")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Platform>(ENTITY_NAME, id(), "platform");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Platform>(platformId());
}

inline const Priority* Label::priority() const {
    if (priority_) {
        return priority_.get();
    }
    if (!is_loaded("priority")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Priority>(ENTITY_NAME, id(), "priority");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Priority>(priorityId());
}

